window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4ec603bb700c581f"]={"versions": [{"id": "FIG-4ec603bb700c581f", "releases": ["R21-11", "R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Scheduling- und Warteschlangen-/Zustandsmodell für AUTOSAR Classic Platform OS Multi-Core-Systeme.</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Visualisierung des dezentralen, asymmetrisch-unabhängigen Task-Schedulings pro Core (gemäß <code>SRS_Os_80008</code>, <code>SWS_Os_00567</code>). Es demonstriert die Kernprinzipien des AUTOSAR-Multi-Core-Betriebssystems:</li>\n<li>Keine globale, Core-übergreifende Ready-Queue.</li>\n<li>Jeder Prozessorkern führt eine eigenständige Scheduling-Instanz mit lokalen Prioritätsstufen aus.</li>\n<li>Physische echte Parallelität (<em>true parallelism</em>) unabhängig von relativen Prioritätsunterschieden zwischen verschiedenen Cores.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Cores (<code>OsCore</code>):</strong></li>\n<li>Drei diskrete Prozessorkerne (<code>Core 0</code>, <code>Core 1</code>, <code>Core 2</code>).</li>\n<li><strong>Prioritätsachsen (<code>Prio</code>):</strong></li>\n<li>Diskrete Prioritätsskala von <code>1</code> (niedrigste dargestellte Priorität) bis <code>5</code> (höchste dargestellte Priorität), lokal gültig pro Kern gemäß OSEK/AUTOSAR-Prioritätsmodell (höhere numerische Werte bedeuten höhere Priorität).</li>\n<li><strong>Task-Entitäten (<code>OsTask</code>):</strong></li>\n<li><strong>Zustand <code>RUNNING</code> (gestrichelte Kontur):</strong></li>\n<li>Core 0: $T_2$ (Priorität 5)</li>\n<li>Core 1: $T_3$ (Priorität 1)</li>\n<li>Core 2: $T_5$ (Priorität 4)</li>\n<li><strong>Zustand <code>READY</code> (durchgezogene Kontur, wartend in Ready-Queue):</strong></li>\n<li>Core 0: $T_1$ und $T_7$ (beide Priorität 3, FIFO-Reihenfolge), $T_6$ (Priorität 2)</li>\n<li>Core 1: Keine wartenden Tasks</li>\n<li>Core 2: $T_8$ (Priorität 3), $T_4$ (Priorität 2)</li>\n<li><strong>Kardinalitäten & statische Bindung:</strong></li>\n<li>Multi-Core-Allokation: Jeder Task ist statisch über seine übergeordnete <code>OsApplication</code> exakt einem Core zugeordnet (<code>1:1</code>-Bindung via <code>OsApplicationCoreAssignment</code>). Dynamische Task-Migration zwischen Cores zur Laufzeit ist im AUTOSAR OS ausgeschlossen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Echte Nebenläufigkeit:</strong></li>\n<li>Die Schedulings auf <code>Core 0</code>, <code>Core 1</code> und <code>Core 2</code> operieren vollständig entkoppelt.</li>\n<li>$T_2$, $T_3$ und $T_5$ werden simultan ausgeführt. Niedrigere Priorität eines Tasks auf einem Core ($T_3$ auf Core 1 mit Prio 1) führt nicht zur Blockierung durch höher priorisierte Tasks auf anderen Cores (wie $T_1, T_7, T_8$ mit Prio 3).</li>\n<li><strong>Intra-Core-Ablauf (Gleicher Core):</strong></li>\n<li>Strikt prioritätsbasiertes Scheduling: Auf Core 0 verdrängt bzw. blockiert $T_2$ (Prio 5) alle niedrigeren Tasks ($T_1, T_7, T_6$).</li>\n<li>FIFO bei identischer Priorität: $T_1$ und $T_7$ teilen sich Priorität 3 auf Core 0. Sobald Prio 3 an die Reihe kommt (nach Terminierung/Warten von $T_2$), entscheidet die historische Aktivierungsreihenfolge (<code>ActivateTask()</code>-Zeitstempel in der internen Ready-Liste).</li>\n<li><strong>Inter-Core-Ablauf (Core-übergreifend):</strong></li>\n<li>Keine deterministische Aktivierungsreihenfolge zwischen Cores: Wird $T_8$ (Core 2, Prio 3) zeitlich vor $T_1$ (Core 0, Prio 3) aktiviert, impliziert dies keinerlei Vorrang für die Ausführung. Der Start hängt rein von der lokalen Last und den lokalen Präemptionen des jeweiligen Kerns ab.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausschluss von implizitem Race-Condition-Schutz:</strong></li>\n<li>Prioritäten schützen <strong>ausschließlich</strong> innerhalb desselben Kerns vor Verdrängung. Ein niederpriorer Task auf Core 1 kann parallel zu einem hochprioren Task auf Core 0 laufen.</li>\n<li>Gemeinsam genutzte globale Datenbereiche dürfen keinesfalls unter der Annahme „Task A hat höhere Priorität als Task B“ ungeschützt bleiben.</li>\n<li><strong>Synchronisationsmechanismen & Ressourcen:</strong></li>\n<li>Das klassische OSEK Priority Ceiling Protocol (<code>GetResource()</code> / <code>ReleaseResource()</code>) ist streng Core-lokal und <strong>nicht</strong> Core-übergreifend wirksam.</li>\n<li>Für Core-übergreifende Synchronisation müssen AUTOSAR-Spinlocks (<code>GetSpinlock()</code> / <code>ReleaseSpinlock()</code>) oder Inter-OS-Application-Kommunikationskanäle (<code>IOC</code>, <em>Inter-OS-Application Communicator</em>) eingesetzt werden.</li>\n<li><strong>Konfiguration & Timing-Analyse (WCRT):</strong></li>\n<li>Bei der Konfiguration im BSW-Editor (<code>OsTaskPriority</code>) existiert kein globales Prioritätsband. Prioritäten müssen pro Core getrennt dimensioniert werden.</li>\n<li>Worst-Case Execution Time (WCET)- und Schedulability-Analysen müssen primär pro Core gerechnet werden, ergänzt um Inter-Core-Blockierzeiten (Spinlock-Locking-Times, IOC-Overhead und Bus-Arbitrierung).</li>\n</ul>"}, {"id": "FIG-336c4b0343f5cb5f", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Scheduling- und Warteschlangen-/Zustandsmodell für AUTOSAR Classic Platform OS Multi-Core-Systeme.</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Visualisierung des dezentralen, asymmetrisch-unabhängigen Task-Schedulings pro Core (gemäß <code>SRS_Os_80008</code>, <code>SWS_Os_00567</code>). Es demonstriert die Kernprinzipien des AUTOSAR-Multi-Core-Betriebssystems:</li>\n<li>Keine globale, Core-übergreifende Ready-Queue.</li>\n<li>Jeder Prozessorkern führt eine eigenständige Scheduling-Instanz mit lokalen Prioritätsstufen aus.</li>\n<li>Physische echte Parallelität (<em>true parallelism</em>) unabhängig von relativen Prioritätsunterschieden zwischen verschiedenen Cores.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Cores (<code>OsCore</code>):</strong></li>\n<li>Drei diskrete Prozessorkerne (<code>Core 0</code>, <code>Core 1</code>, <code>Core 2</code>).</li>\n<li><strong>Prioritätsachsen (<code>Prio</code>):</strong></li>\n<li>Diskrete Prioritätsskala von <code>1</code> (niedrigste dargestellte Priorität) bis <code>5</code> (höchste dargestellte Priorität), lokal gültig pro Kern gemäß OSEK/AUTOSAR-Prioritätsmodell (höhere numerische Werte bedeuten höhere Priorität).</li>\n<li><strong>Task-Entitäten (<code>OsTask</code>):</strong></li>\n<li><strong>Zustand <code>RUNNING</code> (gestrichelte Kontur):</strong></li>\n<li>Core 0: $T_2$ (Priorität 5)</li>\n<li>Core 1: $T_3$ (Priorität 1)</li>\n<li>Core 2: $T_5$ (Priorität 4)</li>\n<li><strong>Zustand <code>READY</code> (durchgezogene Kontur, wartend in Ready-Queue):</strong></li>\n<li>Core 0: $T_1$ und $T_7$ (beide Priorität 3, FIFO-Reihenfolge), $T_6$ (Priorität 2)</li>\n<li>Core 1: Keine wartenden Tasks</li>\n<li>Core 2: $T_8$ (Priorität 3), $T_4$ (Priorität 2)</li>\n<li><strong>Kardinalitäten & statische Bindung:</strong></li>\n<li>Multi-Core-Allokation: Jeder Task ist statisch über seine übergeordnete <code>OsApplication</code> exakt einem Core zugeordnet (<code>1:1</code>-Bindung via <code>OsApplicationCoreAssignment</code>). Dynamische Task-Migration zwischen Cores zur Laufzeit ist im AUTOSAR OS ausgeschlossen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Echte Nebenläufigkeit:</strong></li>\n<li>Die Schedulings auf <code>Core 0</code>, <code>Core 1</code> und <code>Core 2</code> operieren vollständig entkoppelt.</li>\n<li>$T_2$, $T_3$ und $T_5$ werden simultan ausgeführt. Niedrigere Priorität eines Tasks auf einem Core ($T_3$ auf Core 1 mit Prio 1) führt nicht zur Blockierung durch höher priorisierte Tasks auf anderen Cores (wie $T_1, T_7, T_8$ mit Prio 3).</li>\n<li><strong>Intra-Core-Ablauf (Gleicher Core):</strong></li>\n<li>Strikt prioritätsbasiertes Scheduling: Auf Core 0 verdrängt bzw. blockiert $T_2$ (Prio 5) alle niedrigeren Tasks ($T_1, T_7, T_6$).</li>\n<li>FIFO bei identischer Priorität: $T_1$ und $T_7$ teilen sich Priorität 3 auf Core 0. Sobald Prio 3 an die Reihe kommt (nach Terminierung/Warten von $T_2$), entscheidet die historische Aktivierungsreihenfolge (<code>ActivateTask()</code>-Zeitstempel in der internen Ready-Liste).</li>\n<li><strong>Inter-Core-Ablauf (Core-übergreifend):</strong></li>\n<li>Keine deterministische Aktivierungsreihenfolge zwischen Cores: Wird $T_8$ (Core 2, Prio 3) zeitlich vor $T_1$ (Core 0, Prio 3) aktiviert, impliziert dies keinerlei Vorrang für die Ausführung. Der Start hängt rein von der lokalen Last und den lokalen Präemptionen des jeweiligen Kerns ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Ausschluss von implizitem Race-Condition-Schutz:</strong></li>\n<li>Prioritäten schützen <strong>ausschließlich</strong> innerhalb desselben Kerns vor Verdrängung. Ein niederpriorer Task auf Core 1 kann parallel zu einem hochprioren Task auf Core 0 laufen.</li>\n<li>Gemeinsam genutzte globale Datenbereiche dürfen keinesfalls unter der Annahme „Task A hat höhere Priorität als Task B“ ungeschützt bleiben.</li>\n<li><strong>Synchronisationsmechanismen & Ressourcen:</strong></li>\n<li>Das klassische OSEK Priority Ceiling Protocol (<code>GetResource()</code> / <code>ReleaseResource()</code>) ist streng Core-lokal und <strong>nicht</strong> Core-übergreifend wirksam.</li>\n<li>Für Core-übergreifende Synchronisation müssen AUTOSAR-Spinlocks (<code>GetSpinlock()</code> / <code>ReleaseSpinlock()</code>) oder Inter-OS-Application-Kommunikationskanäle (<code>IOC</code>, <em>Inter-OS-Application Communicator</em>) eingesetzt werden.</li>\n<li><strong>Konfiguration & Timing-Analyse (WCRT):</strong></li>\n<li>Bei der Konfiguration im BSW-Editor (<code>OsTaskPriority</code>) existiert kein globales Prioritätsband. Prioritäten müssen pro Core getrennt dimensioniert werden.</li>\n<li>Worst-Case Execution Time (WCET)- und Schedulability-Analysen müssen primär pro Core gerechnet werden, ergänzt um Inter-Core-Blockierzeiten (Spinlock-Locking-Times, IOC-Overhead und Bus-Arbitrierung).</li>\n</ul>"}], "trans": [{"from": "FIG-4ec603bb700c581f", "to": "FIG-336c4b0343f5cb5f", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
